INSERT INTO `agenda` VALUES (1,'Bimbingan Teknis Penyusunan SKP & Penerapan Merit System ASN 2026','bimtek-skp-merit-system-asn-2026','Pengembangan Kompetensi','Pelatihan implementasi evaluasi kinerja berkala pegawai, pemetaan talent pool, dan optimalisasi indeks profesionalitas ASN di lingkungan Pemkab Aceh Tamiang.','Aula Gedung Utama BKPSDM Kabupaten Aceh Tamiang','OFFLINE','2026-10-12 08:00:00','2026-10-14 16:00:00',1,NULL,'2026-10-06 23:03:40','2026-10-06 23:03:40',NULL),(2,'Uji Kompetensi Kenaikan Jenjang Jabatan Fungsional Tertentu (JFT)','uji-kompetensi-kenaikan-jenjang-jft-2026','Jabatan Fungsional','Pelaksanaan asesmen kompetensi teknis, manajerial, dan sosio-kultural bagi pejabat fungsional yang akan naik jenjang jabatan.','Laboratorium CAT BKPSDM Aceh Tamiang','OFFLINE','2026-10-19 08:30:00','2026-10-19 15:30:00',1,NULL,'2026-10-06 23:03:40','2026-10-06 23:03:40',NULL),(3,'Sosialisasi Kebijakan Cuti & Disiplin ASN Berdasarkan PP 94/2021','sosialisasi-kebijakan-cuti-disiplin-pp94-2021','Disiplin & Regulasi','Sosialisasi tata cara pengajuan cuti serta ketentuan penegakan disiplin dan kewajiban masuk kerja bagi aparatur sipil negara.','Aula Utama Setdakab Aceh Tamiang','HYBRID','2026-10-22 09:00:00','2026-10-22 12:00:00',1,NULL,'2026-10-06 23:03:40','2026-10-06 23:03:40',NULL);
