INSERT INTO `berita` VALUES (1,'BKPSDM Aceh Tamiang Terapkan Percepatan Kenaikan Pangkat 6 Periode Berbasis SIASN BKN','bkpsdm-aceh-tamiang-terapkan-percepatan-kenaikan-pangkat-6-periode-siasn','Pemerintah Kabupaten Aceh Tamiang melalui BKPSDM resmi memberlakukan layanan periodisasi Kenaikan Pangkat (KP) 6 kali dalam setahun secara digital terintegrasi BKN.','\n          <p><strong>Karang Baru, Humas BKPSDM</strong> — Pemerintah Kabupaten Aceh Tamiang melalui Badan Kepegawaian dan Pengembangan Sumber Daya Manusia (BKPSDM) secara resmi menerapkan kebijakan baru Badan Kepegawaian Negara (BKN) terkait periodisasi kenaikan pangkat Pegawai Negeri Sipil (PNS) menjadi enam periode dalam setahun.</p>\n          <p>Kepala BKPSDM Kabupaten Aceh Tamiang menjelaskan bahwa kebijakan ini mengacu pada Peraturan BKN Nomor 4 Tahun 2023. Jika sebelumnya kenaikan pangkat hanya dilaksanakan dua kali setahun (April dan Oktober), kini dibuka pada bulan <strong>Februari, April, Juni, Agustus, Oktober, dan Desember</strong>.</p>\n          <h3>Keuntungan Integrasi SIASN bagi ASN Aceh Tamiang</h3>\n          <ul>\n            <li><strong>Proses Lebih Cepat:</strong> Berkas langsung divalidasi secara elektronik tanpa perlu tumpukan fisik.</li>\n            <li><strong>Transparansi Status:</strong> ASN dapat memantau pergerakan usulan mereka melalui aplikasi MyASN dan portal resmi BKPSDM.</li>\n            <li><strong>Tanda Tangan Elektronik:</strong> SK Kenaikan Pangkat diterbitkan dengan sertifikat digital BKN dan ber-barcode resmi.</li>\n          </ul>\n          <p>Seluruh pengelola kepegawaian di masing-masing Organisasi Perangkat Daerah (OPD) diimbau untuk segera memperbarui data kinerja pegawai (SKP) pada e-Kinerja BKN sebelum batas waktu pengusulan setiap periodenya.</p>\n        ','https://images.unsplash.com/photo-1521737604893-d14cc237f11d?auto=format&fit=crop&w=1200&q=80','Koordinasi Pelayanan Kenaikan Pangkat SIASN di Kantor BKPSDM Aceh Tamiang',2,'[2]','62d99adb-e619-4078-988b-aeae781c81db','Bidang Mutasi & Status Kepegawaian BKPSDM','PUBLISHED','2026-10-06 21:03:40',1305,1,1,'Percepatan Kenaikan Pangkat 6 Periode SIASN BKN | BKPSDM Aceh Tamiang','Informasi resmi pelaksanaan periodisasi Kenaikan Pangkat 6 kali setahun berbasis SIASN BKN di lingkungan Pemerintah Kabupaten Aceh Tamiang.','Kenaikan Pangkat PNS Aceh Tamiang, SIASN BKN, Periodisasi KP 6 Kali, BKPSDM Aceh Tamiang, Karir ASN',NULL,4,'2026-10-06 23:03:40','2026-10-09 01:55:37',NULL),(2,'Jadwal dan Ketentuan Pelaksanaan Ujian Dinas & Uji Penyesuaian Ijazah ASN Aceh Tamiang 2026','jadwal-ketentuan-ujian-dinas-dan-penyesuaian-ijazah-asn-aceh-tamiang-2026','BKPSDM Kabupaten Aceh Tamiang mengumumkan jadwal seleksi Ujian Dinas Tingkat I, Tingkat II, serta Ujian Penyesuaian Kenaikan Pangkat Ijazah (UPKPI) dengan sistem CAT.','\n          <p><strong>Karang Baru</strong> — Dalam rangka pengembangan kompetensi serta pembinaan karir Pegawai Negeri Sipil, BKPSDM Kabupaten Aceh Tamiang akan menyelenggarakan Ujian Dinas Tingkat I, Tingkat II, dan Penyesuaian Ijazah berbasis <em>Computer Assisted Test (CAT)</em>.</p>\n          <p>Kegiatan ini merupakan syarat mutlak bagi PNS yang akan pindah golongan dari Golongan II ke Golongan III (Ujian Dinas Tk I), maupun dari Golongan III ke Golongan IV (Ujian Dinas Tk II), serta bagi PNS yang telah memperoleh ijazah sarjana/magister yang telah disetujui izin belajarnya.</p>\n          <h3>Persyaratan Berkas Pendaftaran:</h3>\n          <ol>\n            <li>Surat Usulan dari Kepala Perangkat Daerah pengusul.</li>\n            <li>Salinan SK Pangkat Terakhir dilegalisir.</li>\n            <li>Salinan Ijazah dan Transkrip Nilai yang telah diakui oleh Kementerian / Lembaga terkait.</li>\n            <li>Salinan Surat Izin Belajar / Tugas Belajar yang sah.</li>\n            <li>Penilaian SKP 2 Tahun terakhir dengan nilai minimal \'Baik\'.</li>\n          </ol>\n        ','https://images.unsplash.com/photo-1524178232363-1fb2b075b655?auto=format&fit=crop&w=1200&q=80','Laboratorium CAT BKPSDM Aceh Tamiang',3,'[3]','62d99adb-e619-4078-988b-aeae781c81db','Bidang Pengembangan Kompetensi BKPSDM','PUBLISHED','2026-10-06 15:03:40',860,1,0,'Jadwal Ujian Dinas & Ujian Penyesuaian Ijazah ASN Aceh Tamiang 2026','Informasi persyaratan, pendaftaran dan jadwal pelaksanaan Ujian Dinas Tk I/II dan PI bagi PNS Pemkab Aceh Tamiang.','Ujian Dinas Aceh Tamiang, CAT BKPSDM, Ujian Penyesuaian Ijazah PNS, UPKPI 2026',NULL,3,'2026-10-06 23:03:40','2026-10-09 01:49:05',NULL),(3,'Penetapan Usul NIP dan Jadwal Penyerahan SK PPPK Tenaga Guru dan Teknis Formasi Daerah','penetapan-usul-nip-dan-penyerahan-sk-pppk-guru-teknis-aceh-tamiang','Proses verifikasi berkas penetapan Nomor Induk Pegawai Pemerintah dengan Perjanjian Kerja (NI PPPK) memasuki tahap akhir di Kanreg XIII BKN Banda Aceh.','\n          <p><strong>Karang Baru</strong> — Kabar gembira bagi seluruh calon Pegawai Pemerintah dengan Perjanjian Kerja (PPPK) Kabupaten Aceh Tamiang. Berdasarkan hasil koordinasi dengan Kantor Regional XIII BKN, proses penerbitan Pertimbangan Teknis (Pertek) NI PPPK telah mencapai 98%.</p>\n          <p>Pemerintah Kabupaten Aceh Tamiang menjadwalkan proses penyerahan Petikan Surat Keputusan (SK) dan penandatanganan Perjanjian Kerja secara serentak di hadapan Pj. Bupati Aceh Tamiang pada pertengahan bulan ini.</p>\n        ','https://images.unsplash.com/photo-1577495508048-b635879837f1?auto=format&fit=crop&w=1200&q=80','Proses Verifikasi Berkas CASN di Aula BKPSDM',1,'[1]','62d99adb-e619-4078-988b-aeae781c81db','Bidang Pengadaan & Informasi Kepegawaian','PUBLISHED','2026-10-05 23:03:40',2146,0,0,'Penetapan NIP & Penyerahan SK PPPK Kabupaten Aceh Tamiang','Update penetapan Nomor Induk PPPK Tenaga Guru, Kesehatan dan Teknis Pemerintah Kabupaten Aceh Tamiang.','NIP PPPK Aceh Tamiang, Penyerahan SK PPPK, CASN Aceh Tamiang, Honorer',NULL,3,'2026-10-06 23:03:40','2026-10-09 02:00:34',NULL),(4,'Batas Akhir Sinkronisasi SKP & e-Kinerja BKN Triwulan Berjalan Bagi ASN Aceh Tamiang','batas-akhir-sinkronisasi-skp-e-kinerja-bkn-triwulan-asn-aceh-tamiang','BKPSDM mengimbau seluruh ASN dan Kepala OPD untuk menuntaskan penilaian kinerja berkala pada aplikasi e-Kinerja BKN sebelum tenggat waktu sistem ditutup.','\n          <p><strong>Karang Baru</strong> — Selaras dengan implementasi PermenPAN-RB Nomor 6 Tahun 2022 tentang Pengelolaan Kinerja Pegawai Aparatur Sipil Negara, seluruh ASN di lingkungan Pemerintah Kabupaten Aceh Tamiang diwajibkan melakukan input dan penetapan predikat kinerja triwulanan pada portal <em>e-Kinerja BKN</em>.</p>\n          <p>Sinkronisasi ini menjadi dasar utama dalam verifikasi pencairan Tambahan Penghasilan Pegawai (TPP) serta syarat mutlak pengusulan Kenaikan Pangkat dan Layanan Mutasi.</p>\n        ','https://images.unsplash.com/photo-1460925895917-afdab827c52f?auto=format&fit=crop&w=1200&q=80','Dashboard Pengelolaan e-Kinerja BKN',4,'[4]','62d99adb-e619-4078-988b-aeae781c81db','Bidang Bangkom & Kinerja ASN','PUBLISHED','2026-10-05 11:03:40',644,0,0,'Batas Sinkronisasi SKP e-Kinerja BKN ASN Kab. Aceh Tamiang','Panduan dan batas waktu penilaian SKP triwulan e-Kinerja BKN untuk pencairan TPP ASN Aceh Tamiang.','e-Kinerja BKN, SKP ASN Aceh Tamiang, TPP Pegawai, Penilaian Kinerja',NULL,3,'2026-10-06 23:03:40','2026-10-09 01:30:00',NULL),(5,'Pemberkasan Usul Pensiun Pertama dan Jaminan Hari Tua ASN Melalui SIASN','pemberkasan-usul-pensiun-pertama-dan-jaminan-hari-tua-asn-siasn','BKPSDM Aceh Tamiang mempermudah layanan pensiun pertama bagi PNS yang memasuki BUP dengan penerbitan SK Pensiun Digital.','<p>Pemerintah Kabupaten Aceh Tamiang mengoptimalkan layanan kepensiunan terpadu.</p>','https://images.unsplash.com/photo-1450133064473-71024230f91b?auto=format&fit=crop&w=1200&q=80','Pelayanan Pensiun BKPSDM',2,NULL,NULL,'Bidang Mutasi & Status Kepegawaian','PUBLISHED','2026-10-04 10:00:00',430,0,0,NULL,NULL,NULL,NULL,3,'2026-10-08 18:23:17','2026-10-08 18:23:17',NULL),(6,'Pelatihan Kepemimpinan Pengawas (PKP) Angkatan II Pemkab Aceh Tamiang Resmi Dibuka','pelatihan-kepemimpinan-pengawas-pkp-angkatan-ii-aceh-tamiang','Sebanyak 40 pejabat pengawas mengikuti pelatihan kepemimpinan untuk meningkatkan kompetensi manajerial pelayanan publik.','<p>Kegiatan Pelatihan Kepemimpinan Pengawas diselenggarakan bekerja sama dengan BPSDM Aceh.</p>','https://images.unsplash.com/photo-1517245386807-bb43f82c33c4?auto=format&fit=crop&w=1200&q=80','Pembukaan Diklat PKP di Aula BKPSDM',3,NULL,NULL,'Bidang Bangkom & Diklat','PUBLISHED','2026-10-03 14:30:00',520,0,0,NULL,NULL,NULL,NULL,4,'2026-10-08 18:23:17','2026-10-08 18:23:17',NULL),(7,'Verifikasi Faktual Dokumen Usulan Penyesuaian Ijazah ASN Periode Oktober 2026','verifikasi-faktual-dokumen-usulan-penyesuaian-ijazah-asn-2026','Tim verifikator kepegawaian menuntaskan pemeriksaan berkas akademik pangkalan data Dikti bagi calon peserta ujian dinas.','<p>Verifikasi ijazah dilakukan langsung melalui koordinasi pangkalan data Kemendiktisaintek.</p>','https://images.unsplash.com/photo-1434030216411-0b793f4b4173?auto=format&fit=crop&w=1200&q=80','Pemeriksaan Berkas Kepegawaian',2,NULL,NULL,'Bidang Mutasi & Kepangkatan','PUBLISHED','2026-10-02 09:15:00',612,0,0,NULL,NULL,NULL,NULL,3,'2026-10-08 18:23:17','2026-10-08 18:23:17',NULL),(8,'Sosialisasi Tata Tertib dan Disiplin Kerja ASN Sesuai PP No 94 Tahun 2021','sosialisasi-tata-tertib-dan-disiplin-kerja-asn-pp-94-2021','Mendorong budaya integritas dan akuntabilitas jam kerja ASN di seluruh unit organisasi perangkat daerah Aceh Tamiang.','<p>Sosialisasi disiplin kerja menghadirkan narasumber dari Kanreg XIII BKN.</p>','https://images.unsplash.com/photo-1557804506-669a67965ba0?auto=format&fit=crop&w=1200&q=80','Sosialisasi Disiplin Kerja ASN',4,NULL,NULL,'Bidang Kinerja & Disiplin ASN','PUBLISHED','2026-10-01 11:00:00',789,0,0,NULL,NULL,NULL,NULL,3,'2026-10-08 18:23:17','2026-10-08 18:23:17',NULL),(9,'Bimtek Pemutakhiran Data Mandiri (PDM) MyASN BKN Bagi Pengelola Kepegawaian','bimtek-pemutakhiran-data-mandiri-pdm-myasn-bkn-2026','Seluruh pengelola kepegawaian OPD dilatih untuk memastikan kelengkapan data riwayat jabatan dan keluarga ASN akurat.','<p>Pemutakhiran data secara berkala menjadi kunci kelancaran layanan kenaikan pangkat dan pensiun.</p>','https://images.unsplash.com/photo-1522071820081-009f0129c71c?auto=format&fit=crop&w=1200&q=80','Bimtek MyASN di Lab CAT',1,NULL,NULL,'Bidang Pengadaan & Informasi Kepegawaian','PUBLISHED','2026-09-29 13:45:00',890,0,0,NULL,NULL,NULL,NULL,4,'2026-10-08 18:23:17','2026-10-08 18:23:17',NULL),(10,'Surat Edaran Cuti Tahunan dan Cuti Bersama ASN Menjelang Akhir Tahun 2026','surat-edaran-cuti-tahunan-dan-cuti-bersama-asn-akhir-tahun-2026','BKPSDM menerbitkan petunjuk teknis permohonan cuti tahunan melalui portal SiKEPO untuk memastikan kelancaran pelayanan publik.','<p>Pengajuan cuti ASN dilakukan secara paperless melalui sistem SiKEPO Aceh Tamiang.</p>','https://images.unsplash.com/photo-1499750310107-5fef28a66643?auto=format&fit=crop&w=1200&q=80','Layanan Cuti Online SiKEPO',4,NULL,NULL,'Bidang Kinerja & Disiplin ASN','PUBLISHED','2026-09-27 15:20:00',950,0,0,NULL,NULL,NULL,NULL,2,'2026-10-08 18:23:17','2026-10-08 18:23:17',NULL),(11,'Penyerahan Piagam Penghargaan Satyalancana Karya Satya bagi ASN Berprestasi','penyerahan-piagam-penghargaan-satyalancana-karya-satya-asn-2026','Pemerintah Kabupaten Aceh Tamiang menganugerahkan tanda kehormatan Satyalancana atas dedikasi dan loyalitas pengabdian ASN.','<p>Penganugerahan diserahkan langsung oleh Bupati Aceh Tamiang dalam upacara bendera.</p>','https://images.unsplash.com/photo-1511578314322-379afb476865?auto=format&fit=crop&w=1200&q=80','Penganugerahan Satyalancana di Halaman Setdakab',4,NULL,NULL,'Humas Pemkab Aceh Tamiang','PUBLISHED','2026-09-25 08:30:00',1120,0,0,NULL,NULL,NULL,NULL,3,'2026-10-08 18:23:17','2026-10-08 18:23:17',NULL),(12,'Workshop Penyusunan Peta Jabatan dan Analisis Beban Kerja (ABK) OPD Tahun 2026','workshop-penyusunan-peta-jabatan-dan-analisis-beban-kerja-abk-2026','Optimalisasi formasi ASN berdasarkan kebutuhan riil organisasi perangkat daerah menuju birokrasi yang lincah.','<p>Penyusunan ABK dan Anjab menjadi dasar perencanaan kebutuhan pengadaan ASN mendatang.</p>','https://images.unsplash.com/photo-1542744173-8e7e53415bb0?auto=format&fit=crop&w=1200&q=80','Penyusunan ABK di Aula Setdakab',1,NULL,NULL,'Bidang Pengadaan & Informasi Kepegawaian','PUBLISHED','2026-09-22 10:00:00',675,0,0,NULL,NULL,NULL,NULL,3,'2026-10-08 18:23:17','2026-10-08 18:23:17',NULL);
