INSERT INTO `dokumen_publik` VALUES (1,'Surat Edaran Pelaksanaan Kenaikan Pangkat PNS Periode 6 Kali Tahun 2026','se-pelaksanaan-kenaikan-pangkat-pns-2026','800/142/BKPSDM/2026',2026,'SURAT_EDARAN','Petunjuk teknis pengusulan kenaikan pangkat PNS Aceh Tamiang terintegrasi SIASN BKN.','https://bkpsdm.acehtamiangkab.go.id/docs/SE_KP_2026.pdf',1450,328,'PUBLISHED','2026-10-06 23:51:44','2026-10-06 23:51:44','2026-10-07 02:07:23'),(2,'Peraturan Bupati Aceh Tamiang tentang Tata Kelola Kinerja & TPP ASN','perbup-tata-kelola-kinerja-tpp-asn','PERBUP NO. 18 TAHUN 2025',2025,'PERATURAN_BUPATI','Regulasi pemberian Tambahan Penghasilan Pegawai berbasis e-Kinerja.','https://bkpsdm.acehtamiangkab.go.id/docs/PERBUP_TPP_2025.pdf',2840,512,'PUBLISHED','2026-10-06 23:51:44','2026-10-06 23:51:44','2026-10-07 02:07:25'),(3,'Buku Panduan Teknis Penggunaan SiKEPO v.2.0 bagi Pegawai & Operator OPD','panduan-teknis-sikepo-v2','PANDUAN/BKPSDM/2026',2026,'PANDUAN_SIKEPO','Panduan lengkap modul pengajuan cuti, mutasi, dan pencetakan SK digital.','https://bkpsdm.acehtamiangkab.go.id/docs/Panduan_SiKEPO_v2.pdf',4200,890,'PUBLISHED','2026-10-06 23:51:44','2026-10-06 23:51:44','2026-10-07 02:07:24');
