INSERT INTO `galeri_media` VALUES (1,'Pelantikan & Pengambilan Sumpah Jabatan Fungsional BKPSDM 2026','FOTO','https://images.unsplash.com/photo-1577495508048-b635879837f1?auto=format&fit=crop&w=800&q=80',NULL,'Kegiatan Kedinasan','Suasana pelantikan pejabat fungsional di Aula Setdakab Aceh Tamiang.',124,'PUBLISHED','2026-10-06 23:51:44','2026-10-06 23:51:44',NULL),(2,'Bimtek Optimalisasi Layanan Single Sign-On SiKEPO v.2.0','FOTO','https://images.unsplash.com/photo-1531482615713-2afd69097998?auto=format&fit=crop&w=800&q=80',NULL,'Pengembangan SDM','Pelatihan teknis admin kepegawaian seluruh OPD di Lab CAT BKPSDM.',240,'PUBLISHED','2026-10-06 23:51:44','2026-10-06 23:51:44',NULL),(3,'','FOTO','','','Kegiatan BKPSDM',NULL,0,'PUBLISHED','2026-10-07 01:21:46','2026-10-07 01:21:46','2026-10-07 01:21:47'),(4,'Pelantikan & Pengambilan Sumpah Jabatan Fungsional BKPSDM 2026','FOTO','https://images.unsplash.com/photo-1577495508048-b635879837f1?auto=format&fit=crop&w=800&q=80',NULL,'Kegiatan Kedinasan','Suasana pelantikan pejabat fungsional di Aula Setdakab Aceh Tamiang.',124,'PUBLISHED','2026-10-07 01:47:48','2026-10-07 01:47:48',NULL),(5,'Bimtek Optimalisasi Layanan Single Sign-On SiKEPO v.2.0','FOTO','https://images.unsplash.com/photo-1531482615713-2afd69097998?auto=format&fit=crop&w=800&q=80',NULL,'Pengembangan SDM','Pelatihan teknis admin kepegawaian seluruh OPD di Lab CAT BKPSDM.',240,'PUBLISHED','2026-10-07 01:47:48','2026-10-07 01:47:48',NULL),(6,'Pelantikan & Pengambilan Sumpah Jabatan Fungsional BKPSDM 2026','FOTO','https://images.unsplash.com/photo-1577495508048-b635879837f1?auto=format&fit=crop&w=800&q=80','https://images.unsplash.com/photo-1577495508048-b635879837f1?auto=format&fit=crop&w=800&q=80','Kegiatan Kedinasan','Suasana pelantikan pejabat fungsional di Aula Setdakab Aceh Tamiang.',0,'PUBLISHED','2026-10-08 17:31:27','2026-10-08 17:31:27','2026-10-09 01:12:50'),(7,'Bimtek Optimalisasi Layanan Single Sign-On SiKEPO v.2.0','FOTO','https://images.unsplash.com/photo-1531482615713-2afd69097998?auto=format&fit=crop&w=800&q=80','https://images.unsplash.com/photo-1531482615713-2afd69097998?auto=format&fit=crop&w=800&q=80','Pengembangan SDM','Pelatihan teknis admin kepegawaian seluruh OPD di Lab CAT BKPSDM.',0,'PUBLISHED','2026-10-08 17:31:27','2026-10-08 17:31:27','2026-10-09 01:12:48'),(8,'Tutorial SIASN BKN & Penetapan SK Kenaikan Pangkat ASN','VIDEO','https://www.youtube.com/watch?v=dQw4w9WgXcQ','https://img.youtube.com/vi/dQw4w9WgXcQ/hqdefault.jpg','Edukasi ASN','Panduan teknis pengusulan berkas kenaikan pangkat secara digital melalui SIASN BKN RI.',0,'PUBLISHED','2026-10-08 17:31:27','2026-10-08 17:31:27',NULL),(9,'Reels Dokumentasi Core Values BerAKHLAK ASN Aceh Tamiang','VIDEO','https://www.instagram.com/reel/C3abcde123/','','Sosial Media BKPSDM','Sosialisasi implementasi nilai dasar BerAKHLAK bagi seluruh ASN di Aceh Tamiang.',0,'PUBLISHED','2026-10-08 17:31:27','2026-10-08 17:31:27',NULL),(10,'TikTok Edukasi Alur Layanan Mutasi & Cuti Tahunan ASN','VIDEO','https://www.tiktok.com/@bkpsdmatam/video/7123456789012345678','','Sosial Media BKPSDM','Video singkat dan interaktif alur permohonan cuti dan mutasi antar instansi.',0,'PUBLISHED','2026-10-08 17:31:27','2026-10-08 17:31:27',NULL);
