/*!40000 ALTER TABLE `halaman` DISABLE KEYS */;
INSERT INTO `halaman` VALUES (1,'Visi, Misi & Maklumat Pelayanan BKPSDM','visi-misi','Visi dan misi pembangunan sumber daya manusia aparatur sipil negara di Kabupaten Aceh Tamiang.','<h2>Visi BKPSDM Kabupaten Aceh Tamiang</h2><p>Mewujudkan Manajemen Kepegawaian yang Profesional, Akuntabel, Transparan, dan Berbasis Digital Menuju Smart ASN 2026.</p><h2>Misi</h2><ul><li>Meningkatkan kompetensi dan profesionalisme aparatur sipil negara.</li><li>Mengembangkan sistem informasi manajemen kepegawaian terintegrasi (SiKEPO & SIASN).</li><li>Mewujudkan pelayanan administrasi kepegawaian yang cepat, tepat, dan transparan.</li></ul>',NULL,'DEFAULT','PUBLISHED',2,'2026-10-07 00:08:40','2026-10-09 01:14:57',NULL),(2,'Struktur Organisasi & Pejabat Struktural','struktur-organisasi','Bagan susunan organisasi Badan Kepegawaian & Pengembangan Sumber Daya Manusia Kabupaten Aceh Tamiang.','<h2>Susunan Organisasi BKPSDM</h2><p>BKPSDM Kabupaten Aceh Tamiang dipimpin oleh Kepala Badan, dibantu oleh Sekretaris Badan, Bidang Mutasi & Informasi Kepegawaian, Bidang Pengembangan Kompetensi & Pembinaan, serta Kelompok Jabatan Fungsional.</p>',NULL,'DEFAULT','PUBLISHED',0,'2026-10-07 00:08:40','2026-10-07 00:08:40',NULL),(3,'Tugas Pokok & Fungsi (Tupoksi)','tupoksi','Rincian tugas pokok dan fungsi setiap bidang pada BKPSDM Kabupaten Aceh Tamiang.','<h2>Tugas Pokok</h2><p>Melaksanakan urusan penunjang pemerintahan di bidang kepegawaian dan pengembangan sumber daya manusia aparatur daerah.</p><h2>Fungsi</h2><p>Perumusan kebijakan teknis, pengoordinasian pelaksanaan tugas, pembinaan dan pengawasan kepegawaian ASN se-Kabupaten Aceh Tamiang.</p>',NULL,'DEFAULT','PUBLISHED',0,'2026-10-07 00:08:40','2026-10-07 00:08:40',NULL),(4,'Profil PPID Pembantu BKPSDM','profil-ppid','Struktur dan layanan Pejabat Pengelola Informasi dan Dokumentasi (PPID) Pembantu Kepegawaian.','<h2>PPID Pembantu BKPSDM</h2><p>PPID Pembantu BKPSDM bertugas mengelola dan memberikan pelayanan informasi publik terkait administrasi dan data kepegawaian daerah sesuai Undang-Undang Keterbukaan Informasi Publik.</p>',NULL,'DEFAULT','PUBLISHED',0,'2026-10-07 00:08:40','2026-10-07 00:08:40',NULL),(5,'Daftar Informasi Publik (DIP) ASN','daftar-informasi-publik','Katalog daftar informasi publik yang wajib disediakan dan diumumkan secara berkala.','<h2>Kategori Informasi Publik</h2><ul><li>Informasi Berkala: Laporan Kinerja, Statistik ASN, Regulasi Kepegawaian.</li><li>Informasi Serta Merta: Pengumuman Hasil Seleksi CASN, Informasi Darurat Kepegawaian.</li><li>Informasi Setiap Saat: Standar Pelayanan, SOP Layanan Kepegawaian.</li></ul>',NULL,'DEFAULT','PUBLISHED',0,'2026-10-07 00:08:40','2026-10-07 00:08:40',NULL),(6,'Maklumat Pelayanan Publik ASN','maklumat-pelayanan','Komitmen pelayanan prima bebas pungli dan transparan bagi seluruh ASN Aceh Tamiang.','<p>Dengan ini kami menyatakan sanggup menyelenggarakan pelayanan kepegawaian sesuai standar pelayanan yang telah ditetapkan dan siap menerima sanksi apabila tidak menepati janji.</p>',NULL,'DEFAULT','PUBLISHED',2,'2026-10-07 00:08:40','2026-10-09 01:11:59',NULL);
/*!40000 ALTER TABLE `halaman` ENABLE KEYS */;
UNLOCK TABLES;

