INSERT INTO `kategori_layanan` VALUES ('13e260b1-70e2-4e55-a8dd-ec628f6c899a','Cuti, Disiplin & Pensiun','cuti-disiplin-pensiun','Cuti Tahunan/Melahirkan/Sakit/CLTN, Layanan Pensiun BUP/Janda/Duda, Penegakan Disiplin ASN.','Clock',4,1,'2026-10-06 23:03:40','2026-10-06 23:03:40',NULL),('5843382f-10b3-4585-b6a2-8ce308c228e0','Mutasi & Kenaikan Pangkat','mutasi-kenaikan-pangkat','Kenaikan Pangkat Otomatis BKN, Mutasi Antar-Dinas/Instansi, Penyesuaian Ijazah, Ujian Dinas.','TrendingUp',1,1,'2026-10-06 23:03:40','2026-10-06 23:03:40',NULL),('7d5daa2f-980f-4af3-bd1b-026b740c3784','Pengadaan CASN & Status Pegawai','pengadaan-casn-status-pegawai','Seleksi CPNS & PPPK, Penetapan NIP/NIPPPK, Karpeg/Karis/Karsu Digital, Pendataan Non-ASN.','Users',3,1,'2026-10-06 23:03:40','2026-10-06 23:03:40',NULL),('9e0a2db8-3bc8-42ec-99cb-7520fd7c6469','Pengembangan Kompetensi & Diklat','pengembangan-kompetensi-diklat','Izin Belajar, Tugas Belajar, Pelatihan Kepemimpinan (PKP/PKA), Sertifikasi dan Bimtek Kepegawaian.','GraduationCap',2,1,'2026-10-06 23:03:40','2026-10-06 23:03:40',NULL),('b86b3cc5-cc0e-49c6-8384-9943114261a4','Kinerja, TPP & Kesejahteraan','kinerja-tpp-kesejahteraan','Sinkronisasi e-Kinerja BKN, Verifikasi Pembayaran TPP ASN, Tanda Kehormatan Satyalancana.','CheckCircle2',5,1,'2026-10-06 23:03:40','2026-10-06 23:03:40',NULL);
