INSERT INTO `layanan` VALUES ('68890e23-cd65-48c6-aca6-9fdfe5614f6d','7070577c-3627-4741-b90a-341a7f299a59','b86b3cc5-cc0e-49c6-8384-9943114261a4','BKPSDM-KINERJA-06','Sinkronisasi e-Kinerja BKN & Rekomendasi Pembayaran TPP','sinkronisasi-e-kinerja-bkn-rekomendasi-tpp','Layanan verifikasi capaian Sasaran Kinerja Pegawai (SKP) periodik dan tahunan untuk dasar penerbitan rekomendasi pencairan Tambahan Penghasilan Pegawai (TPP).','PermenPAN-RB No. 6 Tahun 2022 tentang Pengelolaan Kinerja Pegawai ASN & Perbup Aceh Tamiang tentang TPP ASN.','Gratis (Rp 0)','1 - 2 Hari Kerja','Surat Rekomendasi Kinerja & Rekapitulasi Pembayaran TPP Terverifikasi','ONLINE_FULL',NULL,'Senin - Jumat (08.00 - 16.00 WIB)',NULL,1,'AKTIF',0,0,'2026-10-06 23:03:40','2026-10-06 23:03:40',NULL),('87f8f8a5-3815-460f-8268-90780de23e13','463f5aa6-7176-4b1d-801d-c25de4a6d170','13e260b1-70e2-4e55-a8dd-ec628f6c899a','BKPSDM-CUTI-05','Persetujuan Cuti Tahunan, Cuti Sakit & Cuti Besar ASN','persetujuan-cuti-tahunan-sakit-besar-asn','Layanan verifikasi dan penerbitan izin cuti ASN di luar kewenangan kepala dinas definitif (Cuti Besar, Cuti Sakit menahun, Cuti Alasan Penting, Cuti di Luar Tanggungan Negara).','Peraturan BKN No. 24 Tahun 2017 jo. Peraturan BKN No. 7 Tahun 2021 tentang Tata Cara Pemberian Cuti PNS.','Gratis (Rp 0)','1 - 3 Hari Kerja','Surat Izin Cuti Resmi Kepala BKPSDM / Bupati Aceh Tamiang','ONLINE_FULL',NULL,'Senin - Jumat (08.00 - 16.00 WIB)',NULL,1,'AKTIF',0,0,'2026-10-06 23:03:40','2026-10-06 23:03:40',NULL),('8fd11920-fd6e-4d3a-8d44-a8d365813744','45fac6aa-4c80-4354-b793-5d0005ab4fca','13e260b1-70e2-4e55-a8dd-ec628f6c899a','BKPSDM-PENSIUN-04','Layanan Usul Pensiun BUP & Janda/Duda Terintegrasi SIASN','usul-pensiun-bup-janda-duda-siasn','Pengajuan pensiun Batas Usia Pensiun (BUP), Pensiun Atas Permintaan Sendiri (APS), dan Pensiun Janda/Duda/Yatim secara otomatis melalui sistem satu data kepegawaian.','UU No. 20 Tahun 2023 tentang Aparatur Sipil Negara & PP No. 11 Tahun 2017.','Gratis (Rp 0)','10 - 20 Hari Kerja','SK Pensiun BKN / Presiden & Surat Pengantar Pembayaran Tabungan Hari Tua (Taspen)','ONLINE_FULL',NULL,'Senin - Jumat (08.00 - 16.00 WIB)',NULL,1,'AKTIF',0,0,'2026-10-06 23:03:40','2026-10-06 23:03:40',NULL),('bbb89dfd-3d48-4632-9571-75ea2fcd3c91','fbb4c857-b0df-45f0-a37f-eab42896b499','5843382f-10b3-4585-b6a2-8ce308c228e0','BKPSDM-KP-01','Usul Kenaikan Pangkat (KP) PNS Periode 6 Kali Setahun','usul-kenaikan-pangkat-pns-periode-6-kali','Layanan pemrosesan usulan Kenaikan Pangkat Reguler, Pilihan (Jabatan Fungsional/Struktural), dan Penyesuaian Ijazah yang terintegrasi langsung dengan SIASN BKN.','Peraturan BKN No. 4 Tahun 2023 tentang Periodisasi Kenaikan Pangkat PNS (Februari, April, Juni, Agustus, Oktober, Desember).','Gratis (Rp 0)','5 - 14 Hari Kerja','Surat Keputusan (SK) Kenaikan Pangkat Digital Bertandatangan Elektronik BKN','ONLINE_FULL',NULL,'Senin - Jumat (08.00 - 16.00 WIB)',NULL,1,'AKTIF',0,0,'2026-10-06 23:03:40','2026-10-06 23:03:40',NULL),('c43170fd-ea6c-4840-bb95-5cb57c87d966','7070577c-3627-4741-b90a-341a7f299a59','9e0a2db8-3bc8-42ec-99cb-7520fd7c6469','BKPSDM-IBEL-02','Penerbitan Surat Izin Belajar / Tugas Belajar ASN','penerbitan-surat-izin-belajar-tugas-belajar','Pemberian rekomendasi dan izin resmi peningkatan kualifikasi pendidikan formal (S1/S2/S3) bagi Pegawai Negeri Sipil di lingkungan Pemerintah Kabupaten Aceh Tamiang.','SE MenPAN-RB No. 28 Tahun 2021 tentang Pengembangan Kompetensi Pegawai Negeri Sipil Melalui Jalur Pendidikan.','Gratis (Rp 0)','3 - 7 Hari Kerja','Surat Keputusan Izin Belajar / Tugas Belajar Bupati Aceh Tamiang','ONLINE_FULL',NULL,'Senin - Jumat (08.00 - 16.00 WIB)',NULL,1,'AKTIF',0,0,'2026-10-06 23:03:40','2026-10-06 23:03:40',NULL),('e38330c4-9908-4d19-8220-f2ef138c00c3','45fac6aa-4c80-4354-b793-5d0005ab4fca','7d5daa2f-980f-4af3-bd1b-026b740c3784','BKPSDM-CASN-03','Pemberkasan & Penetapan NIP CASN / PPPK Formasi Daerah','pemberkasan-penetapan-nip-casn-pppk','Layanan verifikasi berkas digital ke