CREATE TABLE `permohonan` (
  `id` char(36) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL,
  `nomor_tiket` varchar(50) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'Nomor unik pelacakan tiket layanan (misal: TMG-20260930-001)',
  `user_id` char(36) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL,
  `layanan_id` char(36) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL,
  `nik_pemohon` varchar(16) COLLATE utf8mb4_unicode_ci NOT NULL,
  `nama_pemohon` varchar(150) COLLATE utf8mb4_unicode_ci NOT NULL,
  `telepon_pemohon` varchar(25) COLLATE utf8mb4_unicode_ci NOT NULL,
  `alamat_pemohon` text COLLATE utf8mb4_unicode_ci,
  `catatan_pemohon` text COLLATE utf8mb4_unicode_ci,
  `data_berkas` json DEFAULT NULL COMMENT 'JSON list dokumen yang diunggah pemohon',
  `status` enum('DIAJUKAN','VERIFIKASI_BERKAS','DIPROSES_OPD','MENUNGGU_PERBAIKAN','SELESAI','DITOLAK') COLLATE utf8mb4_unicode_ci DEFAULT 'DIAJUKAN',
