INSERT INTO `testimoni` VALUES (1,'Dr. Hendra Wijaya, M.Si','Analis Kepegawaian Ahli Madya','BKPSDM Kab. Aceh Tamiang','https://images.unsplash.com/photo-1534528741775-53994a69daeb?auto=format&fit=crop&w=200&q=80',5,'Layanan kepegawaian daring BKPSDM Aceh Tamiang sangat memangkas birokrasi. Pengurusan kenaikan pangkat berkala dan SK pensiun sekarang serba transparan dan terpantau real-time.',1,1,'2026-10-09 02:35:02','2026-10-09 02:35:02',NULL),(2,'Rahmat Hidayat, S.Kom','Pranata Komputer Diskominfo Atam','Dinas Komunikasi, Informatika & Persandian','https://images.unsplash.com/photo-1507003211169-0a1dd7228f2d?auto=format&fit=crop&w=200&q=80',5,'Presensi SiKEPO Mobile v2.0 stabil luar biasa. Validasi titik koordinat instansi sangat presisi dan sinkronisasi laporan bulanan e-Kinerja BKN menjadi sangat cepat tanpa antre di kantor.',2,1,'2026-10-09 02:35:02','2026-10-09 02:35:02',NULL),(3,'Siti Nurhaliza, S.Pd','Tenaga Pendidik PPPK Tahap I','Dinas Pendidikan & Kebudayaan','https://images.unsplash.com/photo-1573496359142-b8d87734a5a2?auto=format&fit=crop&w=200&q=80',5,'Pusat informasi seleksi CASN & P3K sangat informatif. Panduan video dan verifikasi dokumen yang jelas membuat kami yang bertugas di pelosok kecamatan tetap terlayani dengan optimal.',3,1,'2026-10-09 02:35:02','2026-10-09 02:35:02',NULL);
/*!40000 ALTER TABLE `testimoni` ENABLE KEYS */;
UNLOCK TABLES;

